const byRegion = await sql(`
  SELECT region, sum(amount) AS total, count(*) AS sales
  FROM read_csv('demo/sales.csv')
  GROUP BY region ORDER BY total DESC`);
const total = d3.sum(byRegion, (d) => d.total);
const width = 560, height = 260, margin = { top: 16, right: 16, bottom: 32, left: 64 };
const x = d3.scaleBand(byRegion.map((d) => d.region), [margin.left, width - margin.right]).padding(0.3);
const y = d3.scaleLinear([0, d3.max(byRegion, (d) => d.total)], [height - margin.bottom, margin.top]).nice();
const svg = d3.create("svg").attr("width", width).attr("height", height)
  .attr("viewBox", [0, 0, width, height]).attr("font-family", "system-ui, sans-serif");
svg.append("g").selectAll("rect").data(byRegion).join("rect")
  .attr("x", (d) => x(d.region)).attr("y", (d) => y(d.total))
  .attr("width", x.bandwidth()).attr("height", (d) => y(0) - y(d.total)).attr("fill", "#3657c8");
svg.append("g").attr("transform", `translate(0,${height - margin.bottom})`).call(d3.axisBottom(x));
svg.append("g").attr("transform", `translate(${margin.left},0)`).call(d3.axisLeft(y).ticks(5, "~s"));
const rows = byRegion.map((d) => `<tr><td>${d.region}</td><td>${d.sales}</td><td>${d.total.toLocaleString("en")}</td></tr>`).join("");
const html = `<title>Demo sales by region</title>
<h1>Demo sales by region</h1>
<p>${d3.sum(byRegion, (d) => d.sales).toLocaleString("en")} sales worth ${total.toLocaleString("en")} in all.</p>
<figure>${svg.node().outerHTML}<figcaption>Sales by region</figcaption></figure>
<table><thead><tr><th>Region</th><th>Sales</th><th>Total</th></tr></thead><tbody>${rows}</tbody></table>`;
return await fs.writeFile("sales-report-draft.html", html);
